function knightDistance(from, to) {
  const parse = (square) => [square.charCodeAt(0) - 97, Number(square[1]) - 1];
  const [tx, ty] = parse(to);
  const jumps = [[1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1], [-2, 1], [-1, 2]];
  const start = parse(from);
  const seen = new Set([start.join(',')]);
  let frontier = [start];
  for (let moves = 0; frontier.length > 0; moves++) {
    const next = [];
    for (const [x, y] of frontier) {
      if (x === tx && y === ty) return moves;
      for (const [dx, dy] of jumps) {
        const nx = x + dx;
        const ny = y + dy;
        const key = nx + ',' + ny;
        if (nx < 0 || nx > 7 || ny < 0 || ny > 7 || seen.has(key)) continue;
        seen.add(key);
        next.push([nx, ny]);
      }
    }
    frontier = next;
  }
  return -1;
}

solution:
Treat the board as a graph: 64 squares, each linked to the squares a knight can reach in one jump. The shortest route in a graph where every step costs the same is found by breadth-first search: explore everything one move away, then everything two moves away, and so on, never revisiting a square.

```js
function knightDistance(from, to) {
  const parse = (square) => [square.charCodeAt(0) - 97, Number(square[1]) - 1];
  const [tx, ty] = parse(to);
  const jumps = [[1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1], [-2, 1], [-1, 2]];
  const start = parse(from);
  const seen = new Set([start.join(',')]);
  let frontier = [start];
  for (let moves = 0; frontier.length > 0; moves++) {
    const next = [];
    for (const [x, y] of frontier) {
      if (x === tx && y === ty) return moves;
      for (const [dx, dy] of jumps) {
        const nx = x + dx;
        const ny = y + dy;
        const key = nx + ',' + ny;
        if (nx < 0 || nx > 7 || ny < 0 || ny > 7 || seen.has(key)) continue;
        seen.add(key);
        next.push([nx, ny]);
      }
    }
    frontier = next;
  }
  return -1;
}
```

`parse` turns `"e4"` into column 4 and row 3, counting from 0. Each round of the loop builds the next frontier: the squares exactly one more move away. The first round that contains the target gives the answer.

Formulas based on distance alone fail near the edges. On an open board, a1 to b2 would take 2 moves, but from the corner the knight has only two jumps available, and the shortest route takes **4**. The search handles this without special cases.
